PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS produto (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER NOT NULL, nome TEXT NOT NULL, categoria TEXT NOT NULL DEFAULT 'Hortaliças', descricao TEXT, foto TEXT, preco REAL NOT NULL, ativo INTEGER NOT NULL DEFAULT 1, data_cadastro TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lote (id INTEGER PRIMARY KEY AUTOINCREMENT, produto_id INTEGER NOT NULL, origem TEXT, data_producao TEXT NOT NULL, data_validade TEXT NOT NULL, quantidade_total INTEGER NOT NULL, quantidade_disponivel INTEGER NOT NULL, quantidade_reservada INTEGER NOT NULL DEFAULT 0, quantidade_vendida INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(produto_id) REFERENCES produto(id));
CREATE TABLE IF NOT EXISTS reserva_estoque (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, lote_id INTEGER NOT NULL, quantidade INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'ATIVA', FOREIGN KEY(lote_id) REFERENCES lote(id));
